const crypto = require('crypto');

const secret = $env.AUTOMATION_WEBHOOK_SECRET || 'dev-secret-key';
const headers = $input.first().json.headers;
const rawBody = JSON.stringify($input.first().json.body);
const signatureHeader = headers['x-automation-signature'] || '';

if (!signatureHeader) {
  throw new Error('Unauthorized: Missing X-Automation-Signature header');
}

const cleanSignature = signatureHeader.startsWith('sha256=') ? signatureHeader.slice(7) : signatureHeader;
const expectedSignature = crypto.createHmac('sha256', secret).update(rawBody, 'utf8').digest('hex');

const sigBuffer = Buffer.from(cleanSignature, 'hex');
const expectedBuffer = Buffer.from(expectedSignature, 'hex');

if (sigBuffer.length !== expectedBuffer.length || !crypto.timingSafeEqual(sigBuffer, expectedBuffer)) {
  throw new Error('Unauthorized: Invalid HMAC signature');
}

return [{ json: $input.first().json.body }];

